 The following example wires the handler and triggers an Excel export from the toolbar. 

<SfTreeGrid DataSource="Data" TValue="BusinessObject" @ref="TreeGrid"> 
    <TreeGridToolbarItems> 
        <TreeGridToolbarItem Items="ToolbarItems.ExcelExport"></TreeGridToolbarItem> 
    </TreeGridToolbarItems> 
    <TreeGridEvents TValue="BusinessObject" 
                   OnToolbarClick="ToolbarClickHandler" 
                   ExcelAggregateTemplateInfo="ExcelAggregateTemplateInfoHandler"> 
    </TreeGridEvents> 
    <TreeGridAggregates> 
        <!-- Define caption/footer/group footer aggregates as needed --> 
    </TreeGridAggregates> 
</SfTreeGrid> 

@code { 
    private SfTreeGrid<BusinessObject> TreeGrid; 

    private async Task ToolbarClickHandler(Syncfusion.Blazor.Navigations.ClickEventArgs args) 
    { 
        if (args.Item.Id?.Contains("ExcelExport", StringComparison.OrdinalIgnoreCase) == true 
            || string.Equals(args.Item.Text, "Excel Export", StringComparison.OrdinalIgnoreCase)) 
        { 
            await TreeGrid.ExportToExcelAsync(); 
        } 
    } 

    // Customize aggregate content/style during Excel export. 
    private void ExcelAggregateTemplateInfoHandler(ExcelAggregateEventArgs args) 
    { 
        // Example: inspect field, then adjust output as needed. 
        // args.Field   => Aggregate target field 
        // args.Column  => Column metadata 
        // Modify args.DisplayText / formatting APIs exposed by args as applicable. 
    } 
}


 The following example wires the handler and triggers an Excel export from the toolbar. 

<SfTreeGrid DataSource="Data" TValue="BusinessObject" @ref="TreeGrid" 
            Toolbar="@(new List<string> { "ExcelExport" })"> 
    <TreeGridEvents TValue="BusinessObject" 
                    OnToolbarClick="ToolbarClickHandler" 
                    ExcelHeaderQueryCellInfoEvent="ExcelHeaderQueryCellInfoHandler"> 
    </TreeGridEvents> 
</SfTreeGrid> 

@code { 
    private SfTreeGrid<BusinessObject> TreeGrid; 

    private async Task ToolbarClickHandler(Syncfusion.Blazor.Navigations.ClickEventArgs args) 
    { 
        if (args.Item.Id?.Contains("ExcelExport", StringComparison.OrdinalIgnoreCase) == true 
            || string.Equals(args.Item.Text, "Excel Export", StringComparison.OrdinalIgnoreCase)) 
        { 
            await TreeGrid.ExportToExcelAsync(); 
        } 
    } 

    // Customize header cell text/style during Excel export. 
    private void ExcelHeaderQueryCellInfoHandler(ExcelHeaderQueryCellInfoEventArgs args) 
    { 
        // args.Column => Column metadata for this header cell 
        // Example: bold header and custom text 
        // args.Cell.CellStyle.Bold = true;
        // args.Cell.Value = args.Column.HeaderText?.ToUpperInvariant(); 
    } 
}


